namespace CityForge.Editor {
[InitializeOnLoad] public static class ScannedMeadowLandscapeStudy {
const string W="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/work/meadow-scanned/", O="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/outputs/", A="Assets/CityForge/Art/Environment/NaturalTerrainLab/";
static double due;static int frame;static ScannedMeadowLandscapeStudy(){EditorApplication.update+=Tick;}
static bool Take(string n){if(!File.Exists(W+n))return false;File.Delete(W+n);return true;}
static void Tick(){if(EditorApplication.isCompiling)return;try{if(!EditorApplication.isPlaying&&Take("build"))Build();if(EditorApplication.isPlaying&&Take("capture")){EditorApplication.isPaused=false;frame=0;due=EditorApplication.timeSinceStartup+5;}if(due>0&&EditorApplication.timeSinceStartup>due){Capture();frame++;due=frame<2?EditorApplication.timeSinceStartup+2:0;}}catch(Exception e){due=0;File.WriteAllText(O+"ScannedMeadow_Error.txt",e.ToString());Debug.LogException(e);}}
static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
const string N="Assets/NatureManufacture Assets/Meadow Environment Dynamic Nature/";
static Texture2D coverage;static Dictionary<Material,Material> mats;static GameObject root;static Terrain terrain;static System.Random rng;static List<string> report;
static float R(){return (float)rng.NextDouble();}
static Material Convert(Material old){if(mats.TryGetValue(old,out var found))return found;var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name="ScannedMeadow_"+old.name;Texture Tex(params string[] names){foreach(var name in names)if(old.HasProperty(name)&&old.GetTexture(name)!=null)return old.GetTexture(name);return null;}m.SetTexture("_BaseMap",Tex("_BaseMap","_MainTex","_BaseColorMap","_Albedo"));var normal=Tex("_BumpMap","_NormalMap");m.SetTexture("_BumpMap",normal);if(normal)m.EnableKeyword("_NORMALMAP");m.SetFloat("_Smoothness",.12f);m.SetFloat("_Cull",0);bool alpha=old.name.ToLower().Contains("grass")||old.name.ToLower().Contains("flower")||old.name.ToLower().Contains("lea")||old.name.ToLower().Contains("bush")||old.name.ToLower().Contains("clover")||old.name.ToLower().Contains("willow");m.SetFloat("_AlphaClip",alpha?1:0);if(alpha){m.EnableKeyword("_ALPHATEST_ON");m.SetFloat("_Cutoff",.38f);m.renderQueue=2450;}m.SetColor("_BaseColor",alpha?new Color(.81f,.84f,.73f,1):Color.white);m.enableInstancing=true;AssetDatabase.DeleteAsset(A+m.name+".mat");AssetDatabase.CreateAsset(m,A+m.name+".mat");mats[old]=m;return m;}
static GameObject Place(string path,Vector3 pos,float height,string name,bool shadow=true){var source=AssetDatabase.LoadAssetAtPath<GameObject>(N+path);if(!source)throw new Exception("Missing "+path);var go=(GameObject)PrefabUtility.InstantiatePrefab(source);go.name=name;go.transform.SetParent(root.transform);go.transform.rotation=Quaternion.Euler(0,R()*360,0);var rs=go.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);if(b.size.y>.001f)go.transform.localScale*=shadow?height/b.size.y:Mathf.Min(height/b.size.y,(path.Contains("clover")?.7f:1.3f)/Mathf.Max(b.size.x,b.size.z));go.transform.position=pos;rs=go.GetComponentsInChildren<Renderer>(true);b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);go.transform.position+=Vector3.up*(pos.y-b.min.y-.025f);foreach(var r in rs){r.sharedMaterials=r.sharedMaterials.Select(Convert).ToArray();r.shadowCastingMode=shadow?ShadowCastingMode.TwoSided:ShadowCastingMode.Off;}return go;}
static void Build(){var scene=EditorSceneManager.OpenScene(A+"PondDenseMargins.unity");terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);root=new GameObject("Scanned Meadow landscape experiment");mats=new Dictionary<Material,Material>();rng=new System.Random(8194);report=new List<string>();int bank=0,trees=0;var sourceMask=GameObject.Find("Ground with meadow, canopy litter and dirt masks").GetComponent<Renderer>().sharedMaterial.GetTexture("_Coverage");var rt=RenderTexture.GetTemporary(sourceMask.width,sourceMask.height,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);Graphics.Blit(sourceMask,rt);var previous=RenderTexture.active;RenderTexture.active=rt;coverage=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);coverage.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);coverage.Apply();RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);
var grasses=new[]{"Grass/Prefabs Grass/prefab_grass_meadow_01_detailed_1.prefab","Grass/Prefabs Grass/prefab_grass_meadow_02_detailed_1.prefab","Grass/Prefabs Grass/prefab_grass_meadow_03_1.prefab","Details/Prefabs/prefab_detail_meadow_clover_01.prefab","Grass/Prefabs Flowers/prefab_flower_chamomile_01_detailed_1.prefab"};
var oldRoot=GameObject.Find("Pond edge low flora experiment");foreach(var t in oldRoot.transform.Cast<Transform>().ToArray()){if(!t.name.Contains("bank patch"))continue;var pos=t.position;pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;int type=bank%11<7?bank%3:bank%11<10?3:4;Place(grasses[type],pos,type==3?.15f+R()*.12f:.45f+R()*.5f,"Scanned bank "+bank,false);UnityEngine.Object.DestroyImmediate(t.gameObject);bank++;}
// Keep the established mature tree positions, firs, and waterline planting.
foreach(var rn in new[]{"Temporary shoreline reflection trees","MapMagic generated woodland, saplings and stones"}){var old=GameObject.Find(rn);foreach(var t in old.transform.Cast<Transform>().ToArray()){if(t.name.StartsWith("Stone")||t.name.Contains("Balsam")||t.GetComponentsInChildren<Renderer>().Length==0)continue;if(Vector2.Distance(new Vector2(t.position.x,t.position.z),new Vector2(133,130))>78)continue;var b=Bounds(t.gameObject);if(b.size.y<12)continue;var pos=t.position;pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;Place("Trees/Baked and Optimised Poplar Prefabs/prefab_Baked_0"+(trees%3+3)+"_Poplar.prefab",pos,Mathf.Clamp(b.size.y,15,22),"Scanned mature poplar "+trees);UnityEngine.Object.DestroyImmediate(t.gameObject);trees++;}}
int shrubs=0,meadow=0,rocks=0;for(int j=0;j<24;j++){float a=j*6.28318f/24;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Vector3 edge=Vector3.zero;for(float radius=12;radius<68;radius+=.25f){edge=new Vector3(133,0,130)+dir*radius;edge.y=terrain.SampleHeight(edge)+terrain.transform.position.y;if(edge.y>7.2f)break;}var pos=edge+dir*(4+R()*4);for(int d=0;d<12&&coverage.GetPixelBilinear(pos.x/256,pos.z/256).g>.12f;d++)pos+=dir*.8f;pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;Place("Bushes/Prefabs/prefab_grey_willow_0"+(j%4+1)+".prefab",pos,1.6f+R()*1.8f,"Scanned bank willow "+shrubs++);
if(j%2==0){pos=edge+dir*(R()*2);pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;Place("Rocks/Rocks/Prefabs/prefab_s_rock_0"+(j%6+1)+".prefab",pos,.4f+R()*.55f,"Scanned bank rock "+rocks++);}
for(int k=0;k<55;k++){pos=edge+dir*(6+R()*13)+new Vector3(-dir.z,0,dir.x)*(R()+R()-1)*6;pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(pos.y<7.3f)continue;var material=GameObject.Find("Ground with meadow, canopy litter and dirt masks").GetComponent<Renderer>().sharedMaterial;var coverage=material.GetTexture("_Coverage") as Texture2D;if(ScannedMeadowLandscapeStudy.coverage.GetPixelBilinear(pos.x/256,pos.z/256).g>.12f)continue;int type=k%12==0?4:k%3==0?3:k%3;Place(grasses[type],pos,type==3?.12f+R()*.13f:.3f+R()*.4f,"Scanned meadow understory "+meadow++,false);}}
UnityEngine.Object.DestroyImmediate(coverage);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,A+"ScannedMeadowLandscape.unity");report.Add($"Replaced {bank} bank plants with scanned grasses, clover and chamomile. Replaced {trees} mature broadleaf trees at existing positions with scanned optimized poplars. Added {shrubs} grey willow shrubs, {rocks} scanned bank rocks, {meadow} clustered meadow plants. Native prefab LODGroups retained; shared cloned URP Lit material copies. Small ground plants cast no shadows. First pass uses static foliage materials; vendor wind shaders not enabled. Original vendor materials and prior scenes unchanged. Existing reeds, lilies, ground material, sun and Crest renderer/materials/waves unchanged.");File.WriteAllLines(O+"ScannedMeadow_Changes.txt",report);Debug.Log("SCANNED MEADOW READY");}
static void Capture(){var c=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();c.orthographicSize=40;c.transform.position=new Vector3(133,8,130)-c.transform.forward*110;c.ResetProjectionMatrix();var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(1920,1080,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1920,1080),0,0);t.Apply();File.WriteAllBytes(O+"ScannedMeadowLandscape_"+frame+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}}
